// Помощники шага «3 - העלאת תמונות ווידאו» (#def18b, #c18c9e). ПРОД, пишущие тесты:
// - мастер создаёт черновик POST rest/v1/business на переходе 1→2 и шлёт PATCH дальше — пропускаются
//   ТОЛЬКО эти запросы (и DELETE своего черновика при очистке), прочие не-GET — abort;
// - генерация AI платная: POST …/integration-endpoints/Core/GenerateImage подменяется (Chromium page.route),
//   фиктивная картинка отдаётся локально;
// - запуск только при QA_REAL_WRITE=1; очистка — удаление черновика через корзину в /mybusinesses.
import { expect, Page, Request } from '@playwright/test';

export const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
export const LOAD = { timeout: 20_000 };
export const REAL_WRITE = process.env.QA_REAL_WRITE === '1';
export const SKIP_REASON =
  'Пишет на прод (черновик объявления «QA-TEST» под user, удаляется в afterEach). Запуск только с QA_REAL_WRITE=1.';

/** Строки удалённых «תמונות גנריות לפי קטגוריה» / «טמפלייטים שמורים» (#c18c9e, #def18b). */
export const REMOVED = ['טמפלייט', 'טמפלייטים זמינים', 'תמונות גנריות'];
export const AI_TITLE = 'יצירת תמונה עם AI';
export const STYLES = ['חזית ייצוגית', 'אווירה פנימית', 'סגנון פרסומי'];

/** Фиктивный результат генерации — на домене media.base44.com (CSP img-src), отдаётся локально. */
export const FAKE_AI_URL = 'https://media.base44.com/qa-auto/QA-AUTO_generated_image.png';
const PNG_1x1 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64',
);

const isBusinessUrl = (url: string) => /\/rest\/v1\/business(\?|$)/.test(url);
const isGenerateImage = (url: string) => /\/integration-endpoints\/Core\/GenerateImage/.test(url);

export type Ctl = {
  draftId: string | null;
  title: string;
  generateCalls: string[];
  /** Не-GET, которые дошли до сервера, кроме разрешённых (черновик) — должно быть пусто. */
  unexpected: string[];
  /** Все не-GET (включая подменённые) — для проверки «без сетевых запросов». */
  writes: string[];
};

/**
 * Блок записи: пропускает только POST business (создание своего черновика), PATCH/DELETE business?id=eq.<свой черновик>;
 * GenerateImage — fulfill { url: FAKE_AI_URL }; FAKE_AI_URL — fulfill PNG; прочие не-GET — abort.
 */
export async function interceptDraft(page: Page, tag: string): Promise<Ctl> {
  const ctl: Ctl = {
    draftId: null,
    title: `QA-TEST QA-AUTO ${tag} ${Date.now()}`,
    generateCalls: [],
    unexpected: [],
    writes: [],
  };

  await page.route('**/*', async (route) => {
    const req = route.request();
    const m = req.method();
    const url = req.url();
    if (url === FAKE_AI_URL) return route.fulfill({ status: 200, contentType: 'image/png', body: PNG_1x1 });
    if (SAFE_METHODS.includes(m)) return route.fallback();
    ctl.writes.push(`${m} ${url}`);
    if (m === 'POST' && isGenerateImage(url)) {
      ctl.generateCalls.push(url);
      return route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ url: FAKE_AI_URL }) });
    }
    if (m === 'POST' && isBusinessUrl(url) && !ctl.draftId) return route.fallback();
    if ((m === 'PATCH' || m === 'DELETE') && isBusinessUrl(url) && ctl.draftId && url.includes(`id=eq.${ctl.draftId}`)) {
      return route.fallback();
    }
    return route.abort('blockedbyclient');
  });

  page.on('requestfinished', (r: Request) => {
    const m = r.method();
    const url = r.url();
    if (SAFE_METHODS.includes(m) || isGenerateImage(url)) return;
    const own = isBusinessUrl(url) && (m === 'POST' || (ctl.draftId !== null && url.includes(`id=eq.${ctl.draftId}`)));
    if (!own) ctl.unexpected.push(`${m} ${url}`);
  });

  return ctl;
}

/** Шаги 1–2 мастера → шаг 3. Запоминает id созданного черновика (ответ на POST business). */
export async function goToPhotosStep(page: Page, ctl: Ctl, category: string) {
  await page.goto('/addbusiness');
  await page.getByPlaceholder('יופיע ככותרת של המודעה שלך').fill(ctl.title);
  await page
    .getByPlaceholder('תרשום את תיאור העסק שלך, חשוב מאוד יעזור לך למכור!')
    .fill('QA-AUTO בדיקה אוטומטית — לא לפרסם. תיאור לבדיקת שלב התמונות.');
  await page.getByPlaceholder('טלפון ליצירת קשר*').fill('0501234567');
  await page.getByPlaceholder('מחיר').fill('100000');
  await page.getByRole('combobox').filter({ hasText: 'קטגוריה' }).click();
  await page.getByRole('option', { name: category, exact: true }).click();
  await expect(page.getByRole('combobox').filter({ hasText: category }), `категория «${category}» выбрана`).toBeVisible();

  const created = page.waitForResponse(
    (r) => r.request().method() === 'POST' && isBusinessUrl(r.url()),
    LOAD,
  );
  await page.getByRole('button', { name: 'שלב הבא' }).click();
  const res = await created;
  expect(res.status(), 'черновик создан (POST business)').toBeLessThan(300);
  const json = await res.json();
  const row = Array.isArray(json) ? json[0] : json;
  ctl.draftId = row?.id ?? null;
  expect(ctl.draftId, 'id черновика из ответа POST business').toBeTruthy();

  await expect(page.getByText('משך פעילות העסק (שנים/חודשים)'), 'шаг 2 «נתונים נוספים»').toBeVisible(LOAD);
  await page.getByRole('button', { name: 'שלב הבא' }).click();
  await expect(page.getByRole('heading', { name: 'העלאת תמונות', exact: true }), 'шаг 3 — фото').toBeVisible(LOAD);
}

/** Карточка стиля AI: самый вложенный блок с названием стиля и кнопкой, без названий других стилей. */
export function styleCard(page: Page, style: string) {
  let card = page.locator('div').filter({ hasText: style }).filter({ has: page.getByRole('button') });
  for (const other of STYLES.filter((s) => s !== style)) card = card.filter({ hasNotText: other });
  return card.last();
}

/**
 * Очистка: /mybusinesses → карточка с названием черновика → корзина (кнопка без текста) →
 * подтверждение (если есть) → DELETE business?id=eq.<id> 2xx → карточки нет.
 */
export async function deleteDraft(page: Page, ctl: Ctl) {
  if (!ctl.draftId) return;
  const id = ctl.draftId;
  await page.goto('/mybusinesses');
  const card = page
    .locator('div')
    .filter({ hasText: ctl.title })
    .filter({ has: page.getByRole('button', { name: 'עריכה' }) })
    .last();
  await expect(card, `карточка черновика ${id} в /mybusinesses — если нет, удалить вручную`).toBeVisible(LOAD);

  const deleted = page.waitForResponse(
    (r) => r.request().method() === 'DELETE' && isBusinessUrl(r.url()) && r.url().includes(id),
    LOAD,
  );
  page.once('dialog', (d) => d.accept());
  await card.getByRole('button').filter({ hasNotText: /\S/ }).last().click();
  const confirm = page
    .getByRole('alertdialog')
    .or(page.getByRole('dialog'))
    .getByRole('button', { name: /מחק|מחיקה|אישור|כן/ })
    .first();
  await Promise.race([deleted, confirm.waitFor({ timeout: LOAD.timeout }).then(() => confirm.click())]).catch(() => {});
  const res = await deleted;
  expect(res.status(), `черновик ${id} удалён (DELETE business)`).toBeLessThan(300);
  await expect(page.getByText(ctl.title), 'карточки черновика больше нет').toHaveCount(0, LOAD);
  ctl.draftId = null;
}
